#include <iostream>
#include <vector>

using namespace std;

int N, M;
int adj[20];
int ans = 0;

void backtrack(int u, int forbidden) {
    if (u == N) {
        ans++;
        return;
    }

    // Opção 1: Não incluir o ingrediente u
    backtrack(u + 1, forbidden);

    // Opção 2: Incluir o ingrediente u (se não for proibido)
    if (!(forbidden & (1 << u))) {
        backtrack(u + 1, forbidden | adj[u]);
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> N >> M)) return 0;

    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u] |= (1 << v);
        adj[v] |= (1 << u);
    }

    backtrack(0, 0);

    // Subtrai 1 para desconsiderar o sanduíche vazio
    cout << ans - 1 << "\n";

    return 0;
}
